{
  "schema_version": 1,
  "template_id": "product-feedback-coordinator",
  "template_version": 1,
  "checks": [
    {
      "id": "identity",
      "title": "Confirm product owner and Crew identity",
      "instructions": "Confirm whether this capability seeds a Product Crew or extends a compatible Crew. Preserve existing identity and name the accountable product decision owner."
    },
    {
      "id": "skill",
      "title": "Verify selected skill",
      "instructions": "Confirm skills/product-feedback-coordinator/SKILL.md exists and product-feedback-coordinator is selected for this Crew."
    },
    {
      "id": "scope",
      "title": "Bind product and feedback scope",
      "instructions": "Record tenant, product, feature or journey, period, affected segment, theme ID and owner. Minimum input: Validated feedback theme or authorized feedback records, product and account scope, current issue or roadmap source, product owner and decision criteria."
    },
    {
      "id": "access",
      "title": "Probe authorized product sources",
      "instructions": "Read one real feedback theme plus current issue/roadmap state. Record source IDs, timestamps, permissions and gaps. Helpdesk/survey exports, product usage records, issue tracker and roadmap through scoped MCPs or files. A read-only first decision uses authorized exports."
    },
    {
      "id": "policy",
      "title": "Agree on decision and privacy rules",
      "instructions": "Confirm how the owner weighs prevalence, severity, strategic fit, current commitments and counterexamples. Record privacy limits and action authority. Do not promise a feature, rank a roadmap by mention count alone, create or close an issue, change priority, publish a plan, or message a customer without owner approval and a separate route."
    },
    {
      "id": "first_result",
      "title": "Produce a sourced first decision brief",
      "instructions": "Produce A product decision brief with theme and feedback IDs, affected scope, existing issue links, evidence gaps, owner decision options and next verification. Cite each claim and denominator. A fictional example does not complete this check."
    },
    {
      "id": "review",
      "title": "Review with product owner",
      "instructions": "Show representative and contrary evidence, exact existing issue match, unknowns, options and recommended next investigation. Record the owner decision or correction."
    },
    {
      "id": "delivery",
      "title": "Choose read-only or issue route",
      "optional": true,
      "instructions": "Read-only chat completes this choice. Any issue creation, status change or customer communication needs a separately approved exact-object route and provider receipt."
    },
    {
      "id": "recurrence",
      "title": "Choose manual or recurring review",
      "optional": true,
      "instructions": "Manual-only completes this choice. A schedule or authenticated feedback event requires reviewed source scope, stable theme IDs, deduplication, cost and notification rules. Re-read current issue, roadmap and product evidence; retain theme and issue IDs, preserve accepted and declined decisions, and report what changed instead of opening duplicate work."
    }
  ],
  "completed_steps": []
}
